import { createMemoryAdapter, createRouter } from "@canonical/router-core";
import { RouterProvider } from "@canonical/router-react";
import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { appRoutes, notFoundRoute } from "../../../routes.js";
import SiteRail from "./SiteRail.js";
import type { SiteRailProps } from "./types.js";

const renderSiteRail = (props: SiteRailProps = {}) =>
  render(
    <RouterProvider
      router={createRouter(appRoutes, {
        adapter: createMemoryAdapter("/components"),
        notFound: notFoundRoute,
      })}
    >
      <SiteRail {...props} />
    </RouterProvider>,
  );

describe("SiteRail", () => {
  it("lists the lenses the router's table declares, in rail order", () => {
    renderSiteRail();
    const nav = screen.getByRole("navigation", { name: "Primary" });
    expect(
      [...nav.querySelectorAll(".lenses .label")].map(
        (label) => label.textContent,
      ),
    ).toEqual([
      "Home",
      "Components",
      "Definitions",
      "Standards",
      "Journeys",
      "Guides",
    ]);
  });

  it("links the site brand to the home route", () => {
    renderSiteRail();
    const brand = screen
      .getByRole("navigation", { name: "Primary" })
      .querySelector(".brand");
    expect(brand).toHaveAttribute("href", "/");
    expect(brand?.textContent).toBe("Pragmadesign system docs");
  });

  it("passes native props through to the rail's nav root", () => {
    renderSiteRail({ className: "is-pinned", id: "site-rail" });
    const nav = screen.getByRole("navigation", { name: "Primary" });
    expect(nav.id).toBe("site-rail");
    expect(nav).toHaveClass("is-pinned");
  });

  it("keeps the utility cluster out of the lens list", () => {
    renderSiteRail();
    const lenses = screen
      .getByRole("navigation", { name: "Primary" })
      .querySelector(".lenses");
    const utilities = screen.getByRole("list", { name: "Utilities" });
    expect(lenses?.contains(utilities)).toBe(false);
    expect(
      utilities.contains(screen.getByRole("link", { name: "Playground" })),
    ).toBe(true);
    expect(
      utilities.contains(screen.getByRole("link", { name: "Demo sign-in" })),
    ).toBe(true);
    expect(
      utilities.contains(screen.getByRole("combobox", { name: "Color theme" })),
    ).toBe(true);
  });

  it("links the demo sign-in to the account route with the demo credential", () => {
    renderSiteRail();
    expect(screen.getByRole("link", { name: "Demo sign-in" })).toHaveAttribute(
      "href",
      "/account?auth=1",
    );
  });
});
